import React from "react";

const Css = () => {
    return (
        <>
            <div className="css-page">

                <div className="css-hero">
                    <span className="css-badge">CSS CHEAT SHEET</span>
                    <h1>CSS Complete Quick Reference</h1>
                    <p>
                        Selectors, Colors, Box Model, Flexbox, Grid,
                        Position, Responsive Design and more.
                    </p>
                </div>

                {/* CSS Syntax */}
                <section className="css-card">
                    <h2>1. CSS Syntax</h2>
                    <pre>
                        {`selector {
    property: value;
}`}
                    </pre>

                    <div className="code-example">
                        <strong>Example:</strong>
                        <pre>
                            {`p {
    color: blue;
    font-size: 20px;
}`}
                        </pre>
                    </div>
                </section>

                {/* Selectors */}
                <section className="css-card">
                    <h2>2. CSS Selectors</h2>

                    <div className="css-table">
                        <div className="table-row table-head">
                            <span>Selector</span>
                            <span>Example</span>
                            <span>Meaning</span>
                        </div>

                        <div className="table-row">
                            <span>*</span>
                            <span>*</span>
                            <span>Select all elements</span>
                        </div>

                        <div className="table-row">
                            <span>Element</span>
                            <span>p</span>
                            <span>Select paragraph</span>
                        </div>

                        <div className="table-row">
                            <span>Class</span>
                            <span>.box</span>
                            <span>Select class</span>
                        </div>

                        <div className="table-row">
                            <span>ID</span>
                            <span>#header</span>
                            <span>Select ID</span>
                        </div>

                        <div className="table-row">
                            <span>Group</span>
                            <span>h1, p</span>
                            <span>Select multiple elements</span>
                        </div>
                    </div>
                </section>

                {/* Colors */}
                <section className="css-card">
                    <h2>3. Colors</h2>
                    <pre>
                        {`color: red;
color: #ff0000;
color: rgb(255, 0, 0);
color: rgba(255, 0, 0, 0.5);
background-color: black;`}
                    </pre>
                </section>

                {/* Text */}
                <section className="css-card">
                    <h2>4. Text Properties</h2>
                    <pre>
                        {`color: red;
font-size: 20px;
font-family: Arial;
font-weight: bold;
font-style: italic;

text-align: center;
text-decoration: underline;
text-transform: uppercase;
line-height: 1.5;
letter-spacing: 2px;
word-spacing: 5px;`}
                    </pre>
                </section>

                {/* Box Model */}
                <section className="css-card">
                    <h2>5. Box Model</h2>

                    <div className="box-model">
                        <div className="box-margin">
                            Margin
                            <div className="box-border">
                                Border
                                <div className="box-padding">
                                    Padding
                                    <div className="box-content">
                                        Content
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                    <pre>
                        {`width: 200px;
height: 100px;

margin: 20px;
padding: 20px;

border: 2px solid black;
box-sizing: border-box;`}
                    </pre>
                </section>

                {/* Background */}
                <section className="css-card">
                    <h2>6. Background</h2>
                    <pre>
                        {`background-color: lightblue;

background-image: url("image.jpg");
background-size: cover;
background-position: center;
background-repeat: no-repeat;`}
                    </pre>
                </section>

                {/* Border */}
                <section className="css-card">
                    <h2>7. Border</h2>
                    <pre>
                        {`border: 2px solid black;
border-radius: 10px;

border-top: 2px solid red;
border-bottom: 2px solid blue;`}
                    </pre>
                </section>

                {/* Flexbox */}
                <section className="css-card">
                    <h2>8. Flexbox</h2>
                    <pre>
                        {`display: flex;

flex-direction: row;
justify-content: center;
align-items: center;

gap: 20px;
flex-wrap: wrap;`}
                    </pre>

                    <div className="flex-demo">
                        <div>1</div>
                        <div>2</div>
                        <div>3</div>
                    </div>
                </section>

                {/* Grid */}
                <section className="css-card">
                    <h2>9. CSS Grid</h2>
                    <pre>
                        {`display: grid;

grid-template-columns: repeat(3, 1fr);
gap: 20px;`}
                    </pre>

                    <div className="grid-demo">
                        <div>1</div>
                        <div>2</div>
                        <div>3</div>
                        <div>4</div>
                        <div>5</div>
                        <div>6</div>
                    </div>
                </section>

                {/* Position */}
                <section className="css-card">
                    <h2>10. Position</h2>
                    <pre>
                        {`position: static;
position: relative;
position: absolute;
position: fixed;
position: sticky;

top: 0;
right: 0;
bottom: 0;
left: 0;`}
                    </pre>
                </section>

                {/* Display */}
                <section className="css-card">
                    <h2>11. Display</h2>
                    <pre>
                        {`display: block;
display: inline;
display: inline-block;
display: flex;
display: grid;
display: none;`}
                    </pre>
                </section>

                {/* Width Height */}
                <section className="css-card">
                    <h2>12. Width & Height</h2>
                    <pre>
                        {`width: 100%;
max-width: 1200px;
min-width: 300px;

height: 200px;
min-height: 100vh;
max-height: 500px;`}
                    </pre>
                </section>

                {/* Shadow */}
                <section className="css-card">
                    <h2>13. Shadow</h2>
                    <pre>
                        {`box-shadow: 0 4px 15px rgba(0,0,0,0.2);

text-shadow: 2px 2px 5px gray;`}
                    </pre>
                </section>

                {/* Transition */}
                <section className="css-card">
                    <h2>14. Transition</h2>
                    <pre>
                        {`transition: all 0.3s ease;

button:hover {
    transform: scale(1.05);
}`}
                    </pre>
                </section>

                {/* Transform */}
                <section className="css-card">
                    <h2>15. Transform</h2>
                    <pre>
                        {`transform: translateX(20px);
transform: translateY(20px);
transform: scale(1.2);
transform: rotate(45deg);`}
                    </pre>
                </section>

                {/* Pseudo */}
                <section className="css-card">
                    <h2>16. Pseudo Classes</h2>
                    <pre>
                        {`:hover
:focus
:active
:first-child
:last-child
:nth-child(2)`}
                    </pre>
                </section>

                {/* Overflow */}
                <section className="css-card">
                    <h2>17. Overflow</h2>
                    <pre>
                        {`overflow: visible;
overflow: hidden;
overflow: scroll;
overflow: auto;`}
                    </pre>
                </section>

                {/* Responsive */}
                <section className="css-card">
                    <h2>18. Media Query</h2>
                    <pre>
                        {`@media (max-width: 768px) {

    .container {
        width: 100%;
    }

    h1 {
        font-size: 28px;
    }
}`}
                    </pre>
                </section>

                {/* Important Properties */}
                <section className="css-card">
                    <h2>19. Most Used CSS Properties</h2>

                    <div className="property-grid">
                        <div>color</div>
                        <div>background</div>
                        <div>font-size</div>
                        <div>font-weight</div>
                        <div>margin</div>
                        <div>padding</div>
                        <div>width</div>
                        <div>height</div>
                        <div>display</div>
                        <div>position</div>
                        <div>border</div>
                        <div>border-radius</div>
                        <div>box-shadow</div>
                        <div>opacity</div>
                        <div>z-index</div>
                        <div>cursor</div>
                    </div>
                </section>

                {/* Quick Tips */}
                <section className="css-card tips-card">
                    <h2>20. CSS Quick Tips</h2>

                    <p>✅ Use <code>box-sizing: border-box;</code></p>
                    <p>✅ Use Flexbox for one-dimensional layouts.</p>
                    <p>✅ Use Grid for two-dimensional layouts.</p>
                    <p>✅ Use Media Queries for responsive websites.</p>
                    <p>✅ Use classes for reusable styling.</p>
                    <p>✅ Avoid unnecessary inline CSS.</p>
                </section>

                <footer className="css-footer">
                    CSS Cheat Sheet • Learn • Practice • Build
                </footer>

            </div>
        </>
    )
}

export default Css
